(50418,'chemistry',44,397,792,'What is the maximum number of orbitals that can be identified with the following quantum numbers?<br>${\\rm{n = 3}},{\\rm{l = 1}},\\,\\,{{\\rm{m}}_{\\rm{l}}}{\\rm{ = 0}}$','[{"text": "${\\\\rm{1}}$", "isCorrect": true}, {"text": "${\\\\rm{2}}$", "isCorrect": false}, {"text": "${\\\\rm{3}}$", "isCorrect": false}, {"text": "${\\\\rm{4}}$", "isCorrect": false}]',0,'Given: ${\\rm{n = 3,}}\\,\\,{\\rm{l = 1,}}\\,\\,{{\\rm{m}}_{\\rm{l}}}{\\rm{ = 0}}$<br>Hence orbitals is 3p <img src=\'/img/data/chemistry/44_50418_explanation_1.png\' alt=\'Question Image\' style=\'max-width:100%;\' /> Hence the number of orbitals identified by ${\\rm{m = 0}}$ can be one only',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50419,'chemistry',44,397,792,'The orbital angular momentum of a p-electron is given as','[{"text": "$\\\\sqrt {\\\\rm{6}} {\\\\rm{.}}\\\\frac{{\\\\rm{h}}}{{{\\\\rm{2\\\\pi }}}}$", "isCorrect": false}, {"text": "$\\\\sqrt {\\\\rm{3}} \\\\frac{{\\\\rm{h}}}{{{\\\\rm{2\\\\pi }}}}$", "isCorrect": false}, {"text": "$\\\\sqrt {\\\\frac{{\\\\rm{3}}}{{\\\\rm{2}}}} \\\\frac{{\\\\rm{h}}}{{\\\\rm{\\\\pi }}}$", "isCorrect": false}, {"text": "$\\\\frac{{\\\\rm{h}}}{{\\\\sqrt {\\\\rm{2}} {\\\\rm{\\\\pi }}}}$", "isCorrect": true}]',3,'Orbital angular momentum ${\\rm{ = }}\\sqrt {{\\rm{l(l + 1)}}} {\\rm{ \\times }}\\frac{{\\rm{h}}}{{{\\rm{2\\pi }}}}$<br>For p-electron $\\left( {{\\rm{l = 1}}} \\right)$<br>${\\rm{ = }}\\sqrt {{\\rm{l(l + 1)}}} {\\rm{ \\times }}\\frac{{\\rm{h}}}{{{\\rm{2\\pi }}}}{\\rm{ = }}\\sqrt {\\rm{2}} {\\rm{ \\times }}\\frac{{\\rm{h}}}{{{\\rm{2\\pi }}}}{\\rm{ = }}\\frac{{\\rm{h}}}{{\\sqrt {{\\rm{2\\pi }}} }}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
