(50586,'chemistry',44,392,780,'In the spectrum of hydrogen atom, ratio of the longest wavelength of Lyman series to the longest wavelength in Balmer series is','[{"text": "$\\\\frac{{\\\\rm{5}}}{{{\\\\rm{27}}}}$", "isCorrect": true}, {"text": "$\\\\frac{{{\\\\rm{27}}}}{{\\\\rm{5}}}$", "isCorrect": false}, {"text": "$\\\\frac{{\\\\rm{3}}}{{\\\\rm{2}}}$", "isCorrect": false}, {"text": "$\\\\frac{{\\\\rm{4}}}{{\\\\rm{9}}}$", "isCorrect": false}]',0,'The longest wavelength of lyman series possesses ${{\\rm{n}}_{\\rm{1}}}{\\rm{ = 1}}$ and ${{\\rm{n}}_{\\rm{2}}}{\\rm{ = 2}}$<br>The longest wavelength of Balmer series posseses ${{\\rm{n}}_{\\rm{1}}}{\\rm{ = 2}}$ and ${{\\rm{n}}_{\\rm{2}}}{\\rm{ = 3}}$<br>$\\frac{{\\rm{1}}}{{{{\\rm{\\lambda }}_{{\\rm{Lyman}}}}}}{\\rm{ = }}{{\\rm{R}}_{\\rm{H}}}\\left( {\\frac{{\\rm{1}}}{{{{\\rm{1}}^{\\rm{2}}}}}{\\rm{ - }}\\frac{{\\rm{1}}}{{{{\\rm{2}}^{\\rm{2}}}}}} \\right){\\rm{ = }}\\frac{{{\\rm{3}}{{\\rm{R}}_{\\rm{H}}}}}{{\\rm{4}}}$<br>$\\frac{{\\rm{1}}}{{{{\\rm{\\lambda }}_{{\\rm{Balmer}}}}}}{\\rm{ = }}{{\\rm{R}}_{\\rm{H}}}\\left( {\\frac{{\\rm{1}}}{{{{\\rm{2}}^{\\rm{2}}}}}{\\rm{ - }}\\frac{{\\rm{1}}}{{{{\\rm{3}}^{\\rm{2}}}}}} \\right){\\rm{ = }}\\frac{{{\\rm{5}}{{\\rm{R}}_{\\rm{H}}}}}{{{\\rm{36}}}}$<br>$\\frac{{\\frac{{\\rm{1}}}{{{{\\rm{\\lambda }}_{{\\rm{Lyman}}}}}}}}{{\\frac{{\\rm{1}}}{{{{\\rm{\\lambda }}_{{\\rm{Balmer}}}}}}}}{\\rm{ = }}\\frac{{\\frac{{{\\rm{3}}{{\\rm{R}}_{\\rm{H}}}}}{{\\rm{4}}}}}{{\\frac{{{\\rm{5}}{{\\rm{R}}_{\\rm{H}}}}}{{{\\rm{36}}}}}} \\Rightarrow \\frac{{{{\\rm{\\lambda }}_{{\\rm{Balmer}}}}}}{{{{\\rm{\\lambda }}_{{\\rm{Lyman}}}}}}{\\rm{ = }}\\frac{{{\\rm{27}}}}{{\\rm{5}}} \\Rightarrow \\frac{{{{\\rm{\\lambda }}_{{\\rm{Lyman}}}}}}{{{{\\rm{\\lambda }}_{{\\rm{Balmer}}}}}}{\\rm{ = }}\\frac{{\\rm{5}}}{{{\\rm{27}}}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50587,'chemistry',44,391,775,'Number of photons having wavelength 632.8 nm, emitted by 5 mW laser source in 1 second is','[{"text": "${\\\\rm{1}}{\\\\rm{.6 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{19}}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{\\\\rm{.6 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{16}}}}$", "isCorrect": true}, {"text": "${\\\\rm{1}}{\\\\rm{.6 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{25}}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{\\\\rm{.6 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{13}}}}$", "isCorrect": false}]',1,'${\\rm{E = }}\\frac{{{\\rm{nhc}}}}{{\\rm{\\lambda }}}$<br>${\\rm{5 \\times 1}}{{\\rm{0}}^{{\\rm{ - 3}}}}{\\rm{J/s = }}\\frac{{{\\rm{n \\times 1240 \\times 1}}{\\rm{.6 \\times 1}}{{\\rm{0}}^{{\\rm{ - 19}}}}}}{{{\\rm{632}}{\\rm{.8}}}}$<br>${\\rm{n = 1}}{\\rm{.6 \\times 1}}{{\\rm{0}}^{{\\rm{16}}}}$',NULL,'Hard','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50588,'chemistry',44,391,776,'A metal surface is illuminated by light of two different wavelengths 248 nm and 310 nm. The maximum speeds of the photoelectrons corresponding to these wavelengths are ${{\\rm{u}}_{\\rm{1}}}$ and  ${{\\rm{u}}_{\\rm{2}}}$, respectively. If the ratio  $\\frac{{{{\\rm{u}}_{\\rm{1}}}}}{{{{\\rm{u}}_{\\rm{2}}}}}{\\rm{ = }}\\frac{{\\rm{2}}}{{\\rm{1}}}$ and  ${\\rm{hc = 1240}}\\,{\\rm{eVnm,}}$ the work function of the metal is nearly,','[{"text": "${\\\\rm{2}}{\\\\rm{.8}}\\\\,{\\\\rm{eV}}$", "isCorrect": false}, {"text": "${\\\\rm{3}}{\\\\rm{.2}}\\\\,\\\\,{\\\\rm{eV}}$", "isCorrect": false}, {"text": "${\\\\rm{3}}{\\\\rm{.7}}\\\\,\\\\,{\\\\rm{eV}}$", "isCorrect": true}, {"text": "${\\\\rm{2}}{\\\\rm{.5}}\\\\,\\\\,{\\\\rm{eV}}$", "isCorrect": false}]',2,'${\\rm{K}}{\\rm{.E}}{\\rm{.}} \\propto {{\\rm{u}}^{\\rm{2}}}$<br>$\\frac{{{{\\rm{u}}_{\\rm{1}}}}}{{{{\\rm{u}}_{\\rm{2}}}}}{\\rm{ = }}\\frac{{\\rm{2}}}{{\\rm{1}}}$<br>$\\frac{{{{\\left( {{\\rm{KE}}} \\right)}_{\\rm{1}}}}}{{{{\\left( {{\\rm{KE}}} \\right)}_{\\rm{2}}}}}{\\rm{ = }}\\frac{{\\rm{4}}}{{\\rm{1}}}$<br>${\\rm{K}}{\\rm{.E = E - }}$ work function (W)<br>${\\rm{ = }}\\frac{{{\\rm{hc}}}}{{\\rm{\\lambda }}}{\\rm{ - W}}$<br>${\\left( {{\\rm{KE}}} \\right)_{\\rm{1}}}{\\rm{ = }}\\frac{{{\\rm{1240}}}}{{{\\rm{248}}}}{\\rm{ - W}}\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,{\\rm{(1)}}$<br>${\\left( {{\\rm{KE}}} \\right)_{\\rm{2}}}{\\rm{ = }}\\frac{{{\\rm{1240}}}}{{{\\rm{310}}}}{\\rm{ - W}}\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,{\\rm{(2)}}$<br>By solving (1) & (2)<br>${\\rm{W = 3}}{\\rm{.7eV}}$',NULL,'Hard','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50589,'chemistry',44,391,775,'The energy required to break 1 mol of Cl-Cl bonds in ${\\rm{C}}{{\\rm{l}}_{\\rm{2}}}$ is  ${\\rm{242}}\\,{\\rm{kJ/mol}}{\\rm{.}}$ The longest wavelength of light capable of breaking a single Cl-Cl bond is','[{"text": "${\\\\rm{594}}\\\\,{\\\\rm{nm}}$", "isCorrect": false}, {"text": "${\\\\rm{640}}\\\\,{\\\\rm{nm}}$", "isCorrect": false}, {"text": "${\\\\rm{700}}\\\\,{\\\\rm{nm}}$", "isCorrect": false}, {"text": "${\\\\rm{494}}\\\\,{\\\\rm{nm}}$", "isCorrect": true}]',3,'Energy required for 1 ${\\rm{C}}{{\\rm{l}}_{\\rm{2}}}$ molecule <br>${\\rm{ = }}\\frac{{{\\rm{242 \\times 1}}{{\\rm{0}}^{\\rm{3}}}}}{{{{\\rm{N}}_{\\rm{A}}}}}{\\rm{J}}$<br>${\\rm{E = }}\\frac{{{\\rm{hc}}}}{{\\rm{\\lambda }}}$ or ${\\rm{\\lambda  = }}\\frac{{{\\rm{hc}}}}{{\\rm{E}}}$<br>${\\rm{ = }}\\frac{{{\\rm{6}}{\\rm{.626 \\times 1}}{{\\rm{0}}^{{\\rm{ - 34}}}}{\\rm{ \\times 3 \\times 1}}{{\\rm{0}}^{\\rm{8}}}{\\rm{ \\times 6}}{\\rm{.02 \\times 1}}{{\\rm{0}}^{{\\rm{23}}}}}}{{{\\rm{242 \\times 1}}{{\\rm{0}}^{\\rm{3}}}}}$<br>${\\rm{ = 494 \\times 1}}{{\\rm{0}}^{{\\rm{ - 9}}}}{\\rm{m = 494}}\\,{\\rm{nm}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
