(50677,'chemistry',44,392,780,'Which transition of the hydrogen spectrum would have the same wavelength as the Balmer transition, ${\\rm{n = 4}}$ to ${\\rm{n = 2}}$ of  ${\\rm{H}}{{\\rm{e}}^{\\rm{ + }}}$ spectrum?','[{"text": "${{\\\\rm{n}}_{\\\\rm{2}}}{\\\\rm{ = 2}}\\\\,\\\\,{\\\\rm{to}}\\\\,\\\\,{{\\\\rm{n}}_{\\\\rm{1}}}{\\\\rm{ = 1}}$", "isCorrect": true}, {"text": "${{\\\\rm{n}}_{\\\\rm{2}}}{\\\\rm{ = 3}}\\\\,\\\\,{\\\\rm{to}}\\\\,\\\\,{{\\\\rm{n}}_{\\\\rm{1}}}{\\\\rm{ = 1}}$", "isCorrect": false}, {"text": "${{\\\\rm{n}}_{\\\\rm{2}}}{\\\\rm{ = 4}}\\\\,\\\\,{\\\\rm{to}}\\\\,\\\\,{{\\\\rm{n}}_{\\\\rm{1}}}{\\\\rm{ = 2}}$", "isCorrect": false}, {"text": "${{\\\\rm{n}}_{\\\\rm{1}}}{\\\\rm{ = 2}}{\\\\mkern 1mu} {\\\\mkern 1mu} {\\\\rm{to}}{\\\\mkern 1mu} {\\\\mkern 1mu} {{\\\\rm{n}}_{\\\\rm{1}}}{\\\\rm{ = 3}}$", "isCorrect": false}]',0,'For  ${\\rm{H}}{{\\rm{e}}^{\\rm{ + }}}$ ion, we have<br>$\\frac{{\\rm{1}}}{{\\rm{\\lambda }}}{\\rm{ = }}{{\\rm{R}}_{\\rm{H}}}{{\\rm{Z}}^{\\rm{2}}}\\left[ {\\frac{{\\rm{1}}}{{{{\\rm{n}}_{\\rm{1}}}^{\\rm{2}}}}{\\rm{ - }}\\frac{{\\rm{1}}}{{{{\\rm{n}}_{\\rm{2}}}^{\\rm{2}}}}} \\right]$<br>${\\rm{ = }}{{\\rm{R}}_{\\rm{H}}}{{\\rm{[2]}}^{\\rm{2}}}\\left[ {\\frac{{\\rm{1}}}{{{{\\rm{2}}^{\\rm{2}}}}}{\\rm{ - }}\\frac{{\\rm{1}}}{{{{\\rm{4}}^{\\rm{2}}}}}} \\right]$<br>${\\rm{ = }}\\frac{{\\rm{3}}}{{\\rm{4}}}{{\\rm{R}}_{\\rm{H}}}{\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} \\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,\\,({\\rm{1}})$<br>Now for H atom<br>$\\frac{{\\rm{1}}}{\\lambda }{\\rm{ = }}{{\\rm{R}}_{\\rm{H}}}\\left[ {\\frac{{\\rm{1}}}{{{{\\rm{n}}_{\\rm{1}}}^{\\rm{2}}}}{\\rm{ - }}\\frac{{\\rm{1}}}{{{{\\rm{n}}_{\\rm{2}}}^{\\rm{2}}}}} \\right]{\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} {\\mkern 1mu} ({\\rm{2}})$<br>Equating (1) and (2) we have<br>$\\frac{{\\rm{1}}}{{{{\\rm{n}}_{\\rm{1}}}^{\\rm{2}}}}{\\rm{ - }}\\frac{{\\rm{1}}}{{{{\\rm{n}}_{\\rm{2}}}^{\\rm{2}}}}{\\rm{ = }}\\frac{{\\rm{3}}}{{\\rm{4}}}$<br>Obviously  ${{\\rm{n}}_{\\rm{1}}}{\\rm{ = 1}}$ and  ${{\\rm{n}}_{\\rm{1}}}{\\rm{ = 2}}$. Hence the transition  ${\\rm{n = 2}}$ to  ${\\rm{n = 1}}$ in hydrogen atom, will have the same wavelength as the transition ${\\rm{n = 4}}$ to ${\\rm{n = 2}}$ in ${\\rm{H}}{{\\rm{e}}^{\\rm{ + }}}$ species.',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50678,'chemistry',44,391,775,'Which of the following relates to photons both as wave motion and stream of particles?','[{"text": "${\\\\rm{Interference}}$", "isCorrect": false}, {"text": "${\\\\rm{E = m}}{{\\\\rm{c}}^{\\\\rm{2}}}$", "isCorrect": false}, {"text": "${\\\\rm{Diffraction}}$", "isCorrect": false}, {"text": "${\\\\rm{E = hv}}$", "isCorrect": true}]',3,'According to Planck’s quantum theory, ${\\rm{E = hv = }}\\frac{{{\\rm{hc}}}}{{\\rm{\\lambda }}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50679,'chemistry',44,391,775,'The dimension of Planck’s constant are same as','[{"text": "Energy", "isCorrect": false}, {"text": "Angular momentum", "isCorrect": true}, {"text": "Work", "isCorrect": false}, {"text": "Power", "isCorrect": false}]',1,'Plank’s constant, h and angular momentum, mvr have same units kg ${{\\rm{m}}^{\\rm{2}}}{{\\rm{s}}^{{\\rm{ - 1}}}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50680,'chemistry',44,391,775,'How many photons of light having a wavelength of ${\\rm{4000}}\\,\\mathop {\\rm{A}}\\limits^{\\rm{^\\circ }} $ are necessary to provide 1 J of energy? ${\\rm{(h = 6}}{\\rm{.63 \\times 1}}{{\\rm{0}}^{{\\rm{ - 34}}}}{\\rm{J}}{\\rm{.s,c = 3 \\times 1}}{{\\rm{0}}^{\\rm{8}}}{\\rm{m/s)}}$','[{"text": "${\\\\rm{2}}{\\\\rm{.01 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{18}}}}$", "isCorrect": true}, {"text": "${\\\\rm{4}}{\\\\rm{.97 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{18}}}}$", "isCorrect": false}, {"text": "${\\\\rm{1}}{{\\\\rm{0}}^{{\\\\rm{18}}}}$", "isCorrect": false}, {"text": "${\\\\rm{6 \\\\times 1}}{{\\\\rm{0}}^{{\\\\rm{23}}}}$", "isCorrect": false}]',0,'Energy of a photon ${\\rm{ = hv = }}\\frac{{{\\rm{hc}}}}{{\\rm{\\lambda }}}$<br>${\\rm{ = }}\\frac{{{\\rm{(6}}{\\rm{.63 \\times 1}}{{\\rm{0}}^{{\\rm{ - 34}}}}{\\rm{J}}{\\rm{.s)(3 \\times 1}}{{\\rm{0}}^{\\rm{8}}}{\\rm{m/s)}}}}{{{\\rm{(4000 \\times 1}}{{\\rm{0}}^{{\\rm{ - 10}}}}{\\rm{m)}}}}$<br>${\\rm{ = 4}}{\\rm{.97 \\times 1}}{{\\rm{0}}^{{\\rm{ - 19}}}}{\\rm{J}}{\\rm{.}}$<br>Number of photons required<br>${\\rm{ = }}\\frac{{{\\rm{1J}}}}{{{\\rm{4}}{\\rm{.97 \\times 1}}{{\\rm{0}}^{{\\rm{ - 19}}}}{\\rm{J}}}}{\\rm{ = 2}}{\\rm{.01 \\times 1}}{{\\rm{0}}^{{\\rm{18}}}}$',NULL,'Medium','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50681,'chemistry',44,391,775,'Ratio of energy of a photon of wavelength 200 nm to that of 400 nm is','[{"text": "$\\\\frac{{\\\\rm{1}}}{{\\\\rm{4}}}$", "isCorrect": false}, {"text": "${\\\\rm{4}}$", "isCorrect": false}, {"text": "$\\\\frac{{\\\\rm{1}}}{{\\\\rm{2}}}$", "isCorrect": false}, {"text": "${\\\\rm{2}}$", "isCorrect": true}]',3,'${\\rm{E}} \\propto \\frac{{\\rm{1}}}{{\\rm{\\lambda }}} \\Rightarrow \\frac{{{{\\rm{E}}_{\\rm{1}}}}}{{{{\\rm{E}}_{\\rm{2}}}}}{\\rm{ = }}\\frac{{{{\\rm{\\lambda }}_{\\rm{2}}}}}{{{{\\rm{\\lambda }}_{\\rm{1}}}}}{\\rm{ = }}\\frac{{{\\rm{400}}}}{{{\\rm{200}}}}{\\rm{ = 2}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
(50682,'chemistry',44,391,775,'What would be the ratio of energy of a photon of frequency  $x\\,{s^{ - 1}}$ to $y\\,{s^{ - 1}}$?','[{"text": "${\\\\rm{xy}}$", "isCorrect": false}, {"text": "${\\\\rm{x/y}}$", "isCorrect": true}, {"text": "${\\\\rm{y/x}}$", "isCorrect": false}, {"text": "${\\\\rm{x + y}}$", "isCorrect": false}]',1,'${\\rm{E}} \\propto {\\rm{v}} \\Rightarrow \\frac{{{{\\rm{E}}_{\\rm{1}}}}}{{{{\\rm{E}}_{\\rm{2}}}}}{\\rm{ = }}\\frac{{{{\\rm{v}}_{\\rm{1}}}}}{{{{\\rm{v}}_{\\rm{2}}}}}{\\rm{ = }}\\frac{{\\rm{x}}}{{\\rm{y}}}$',NULL,'Easy','MCQ',NULL,NULL,'2026-07-25 18:34:34.081508',NULL),
